messages.content:
[
 {
  "id": "H1",
  "name": "Hartwell Careers ranking (Smart Shortlist)",
  "description": "Smart Shortlist reads each application and resume against the requisition and shows recruiters a ranked list with a match score from 0 to 100. Since February 2027 it changes no statuses: the rank is a sortable column and recruiters read every application. The vendor says the recruiter always makes the final decision."
 },
 {
  "id": "H2",
  "name": "Resume parser into the talent pool",
  "description": "The parser extracts names, contact details, employers, dates, qualifications and licenses from uploaded resumes into the fields of the talent-pool database so recruiters can search them. It does not score, rank or filter anyone."
 },
 {
  "id": "H3",
  "name": "Skills inventory and vacancy matching",
  "description": "Built by Hartwell's HR-technology engineers on the HCM suite's skills module. It infers each salaried employee's skills from project records, timesheet codes, learning history and the documents they author, keeps a skills profile, and sorts internal vacancies for each employee by match. Managers see team skills heat maps."
 },
 {
  "id": "H4",
  "name": "AskHartwell service agent",
  "description": "An employee-service agent that answers policy questions, books leave within balance when the employee asks, changes a home address on request, and hands sickness and other sensitive questions to an HR adviser. Conversations are logged per employee for quality review."
 },
 {
  "id": "H5",
  "name": "Rotterdam shift and task allocation",
  "description": "Allocates shifts and daily task lists across port-facility crews. It scores each worker on reliability (late arrivals, swaps, absences) and productivity from handheld scans, then builds the roster. Supervisors can edit before publication; the roster publishes automatically at 18:00 if nobody does."
 },
 {
  "id": "H6",
  "name": "Performance evidence summary (F02)",
  "description": "Drafts, for each manager, a summary of an employee's year from goals, project records and peer feedback, before the manager writes the rating. The vendor calls it a preparatory task: the manager decides the rating."
 },
 {
  "id": "H7",
  "name": "Screening audit analytics",
  "description": "People Analytics runs a quarterly analysis of anonymized screening outcomes by step and group to find adverse impact after decisions are made. No individual is scored and no output reaches a live requisition."
 },
 {
  "id": "H8",
  "name": "Video interview engagement score (offered)",
  "description": "An add-on to one-way video interviews that reads facial expression and voice to score each candidate's enthusiasm and confidence, to help recruiters spot engaged candidates."
 },
 {
  "id": "A1",
  "name": "Aurelia call-quality scoring",
  "description": "Scores every recorded call handled by service advisers in Utrecht on script adherence, resolution and handling time, and feeds weekly coaching lists and the monthly review."
 },
 {
  "id": "A2",
  "name": "Aurelia adviser wellbeing signal (offered)",
  "description": "A wellbeing add-on that detects stress and frustration in the adviser's voice during calls and alerts the team leader so they can offer a break."
 },
 {
  "id": "P1",
  "name": "Hollis Plzen maintenance job allocation",
  "description": "A lookup table in the maintenance system assigns each CNC maintenance job to the first available technician who holds the certificate the job requires. No learning or scoring."
 },
 {
  "id": "F1",
  "name": "Fieldnote applicant ranking (EU roles)",
  "description": "Fieldnote's US applicant tracking system ranks applicants for every role, including Dublin roles and roles employed through an employer of record in Spain, Poland and Portugal. The ranking is configured in Austin. Recruiters open the 30 top-ranked applications for each role; the rest receive an automatic rejection email after 21 days."
 }
]
